"""路径、逐跳策略与规则证据；不执行主动探测。"""
import ipaddress
from hep_lfx import business


def matches(asset, selector):
    if not selector or selector.get("bizIds") or selector.get("scope") not in ("ASSETS", "ALL", None):
        raise ValueError("规则含当前无法解析的选择条件")
    if not any(selector.get(key) for key in ("cidrs", "networkTiers", "assetTypes")) and selector.get("scope") != "ALL":
        raise ValueError("规则没有明确的目标条件")
    return (not selector.get("cidrs") or any(ipaddress.ip_address(asset.get("ip", "")) in ipaddress.ip_network(cidr, strict=False) for cidr in selector["cidrs"])) and (not selector.get("networkTiers") or asset.get("networkTier") in selector["networkTiers"]) and (not selector.get("assetTypes") or asset.get("assetType") in selector["assetTypes"])


def mode(value):
    shared = business().snapshot()
    return "explicit" if value.get("reachability") else "rulesError" if shared.get("rules_error") else "rules" if any(rule.get("enabled") in (True, 1) for rule in shared["rules"]) else "noRules"


def targets(value, kind):
    shared = business().snapshot()
    if kind == "explicit":
        return {**value, "prior": [], "items": [{**value["reachability"], "mode": value["reachability"].get("mode", "FULL"), "ruleType": "REQUIRED"}]}
    if kind in ("rulesError", "noRules"):
        return {**value, "items": [{"status": "failed" if kind == "rulesError" else "unknown", "message": "可达性规则读取失败，未核查路径" if kind == "rulesError" else "没有启用的可达性规则；需补充源、目的地址或配置规则", "facts": {"rules": shared["rules"], "rules_frozen_at": shared["rules_frozen_at"], "error": shared.get("rules_error")}}]}
    pairs, items = [], []
    for rule in shared["rules"]:
        if rule.get("enabled") not in (True, 1):
            continue
        try:
            port, protocol = rule.get("destPort"), rule.get("protocol")
            if rule.get("selectorIssues") or rule.get("ruleType") not in ("FORBIDDEN", "REQUIRED") or rule.get("allowedPorts") or port and (not str(port).isdigit() or not 1 <= int(port) <= 65535) or protocol and str(protocol).lower() not in ("tcp", "udp", "icmp"):
                raise ValueError("规则存在选择器问题或当前无法解释的策略条件")
            sources = [asset for asset in shared["assets"] if matches(asset, rule.get("sourceSelector"))]
            destinations = [asset for asset in shared["assets"] if matches(asset, rule.get("destSelector"))]
            if not sources or not destinations:
                raise ValueError("冻结范围内未匹配到规则的完整检查对，未核查该规则")
            seen = set()
            for source in sources:
                for destination in destinations:
                    src, dst = str(ipaddress.ip_address(source.get("ip", ""))), str(ipaddress.ip_address(destination.get("ip", "")))
                    if src == dst or (src, dst) in seen:
                        continue
                    seen.add((src, dst))
                    pairs.append({"rule": rule, "ruleId": rule.get("id"), "ruleName": rule.get("name"), "ruleType": rule["ruleType"], "srcIp": src, "dstIp": dst, "mode": "FULL", **({"port": int(port)} if port else {}), **({"protocol": protocol.lower()} if protocol else {})})
            if not seen:
                raise ValueError("规则只匹配同一地址，未生成跨地址检查对")
        except (ValueError, TypeError) as error:
            items.append({"ruleId": rule.get("id"), "ruleName": rule.get("name"), "status": "unknown", "message": str(error), "facts": {"rule": rule}})
    return {**value, "prior": items, "items": pairs}


def conclusion(value, status, message):
    return {**{key: item for key, item in value["item"].items() if key != "rule"}, "status": status, "message": message, "facts": value.get("facts", {}), "recommendation": "核对拓扑、路由与逐跳访问策略；路径计算不证明实际业务连通或已执行主动探测。" if status != "normal" else None}


async def path(value):
    pair = value["item"]
    try:
        result = (await business().request("graph", "get_reachability_path_by_ip", {"srcIp": pair["srcIp"], "dstIp": pair["dstIp"]})).get("data")
        return {**value, "facts": {"rule": pair.get("rule"), "path": result, "path_observed_at": business().now()}}
    except Exception as error:
        return {**value, "early": conclusion(value, "failed", str(error))}


def evidence(value):
    if value.get("early"):
        return value
    pair, path = value["item"], value["facts"]["path"]
    def done(status, message):
        return {**value, "early": conclusion(value, status, message)}
    if not isinstance(path, dict) or not (path.get("reachable") is True and path.get("verdict") == "REACHABLE" or path.get("reachable") is False and path.get("verdict") == "UNREACHABLE"):
        return done("unknown", "路径缺少一致的可达性证据")
    if path.get("natApplied") is True or path.get("viaSrcIp") and path["viaSrcIp"] != pair["srcIp"] or path.get("viaDstIp") and path["viaDstIp"] != pair["dstIp"]:
        return done("unknown", "路径涉及地址转换，当前接口证据不足以关联端到端策略")
    if not path["reachable"]:
        return done("normal" if pair["ruleType"] == "FORBIDDEN" else "abnormal", "SOC 计算路径不可达；未执行主动探测")
    nodes = path.get("routeOnlyPath", path.get("path"))
    if not isinstance(nodes, list):
        return done("unknown", "路径没有逐跳节点")
    if pair.get("mode") == "MUST_PASS" and not all(str(node) in map(str, nodes) for node in pair.get("via", [])):
        return done("abnormal", "计算路径未经过指定的全部节点")
    devices = sorted(set(str(node) for node in nodes if str(node).isdigit()))
    if not devices and path.get("reason") == "l2_same_segment":
        return {**value, "devices": [], "policy": "permit", "facts": {**value["facts"], "policy": {"status": "not_applicable", "reason": "SOC 明确为同网段二层路径，无过境设备"}}}
    if not devices:
        return done("unknown", "计算路径可达，逐跳 ACL 证据不完整；不据此宣称业务可达")
    return {**value, "devices": devices}


async def acl(value):
    pair, devices, facts, policy = value["item"], value["devices"], {**value["facts"]}, "unknown"
    try:
        response = await business().request("graph", "get_reachability_acl_hit", {"srcIp": pair["srcIp"], "dstIp": pair["dstIp"], "devices": ",".join(devices), **{key: pair[key] for key in ("port", "protocol") if pair.get(key)}})
        facts.update(policy=response.get("data"), policy_observed_at=business().now())
        hops = response.get("data", {}).get("hops")
        if isinstance(hops, list):
            ids = [str(hop.get("deviceId")) for hop in hops]
            if len(ids) == len(devices) and len(set(ids)) == len(ids) and set(ids) == set(devices):
                if any(hop.get("verdict") == "DENY" for hop in hops):
                    policy = "deny"
                elif all(hop.get("verdict") in ("PERMIT", "NO_TRANSIT_FILTER") for hop in hops):
                    policy = "permit"
    except Exception as error:
        facts["policy_error"] = str(error)
    return {**value, "facts": facts, "policy": policy}


def assess(value):
    if value.get("early"):
        return value["early"]
    policy, pair = value.get("policy", "unknown"), value["item"]
    if policy == "unknown":
        return conclusion(value, "unknown", "计算路径可达，逐跳 ACL 证据不完整；不据此宣称业务可达")
    permitted = policy == "permit"
    compliant = not permitted if pair["ruleType"] == "FORBIDDEN" else permitted
    return conclusion(value, "normal" if compliant else "abnormal", "计算路径可达，" + ("策略拒绝" if policy == "deny" else "策略允许或无过境过滤") + "；" + ("按禁止可达规则核对" if pair["ruleType"] == "FORBIDDEN" else "按要求可达目标核对") + ("，未验证具体业务端口" if not pair.get("port") else ""))


def summary(value):
    return business().summary("reachability", {"items": value.get("prior", []) + value["items"]})
